  def genTestSuite(testCases: ISZ[(Z, ISZ[ST])]): Unit = {
    val tq = "\"\"\""

    val testRoot = Os.path(".") / "src" / "test" / "bridge"

    val FCI_Command_Intake_Thread_control_process_fci_command_intake_id = Arch.Autopilot_Engagement_System_Instance_control_process_fci_command_intake.id
    val Engagement_Decision_Thread_control_process_engagement_decision_id = Arch.Autopilot_Engagement_System_Instance_control_process_engagement_decision.id
    val Guidance_Request_Delivery_Thread_control_process_guidance_request_delivery_id = Arch.Autopilot_Engagement_System_Instance_control_process_guidance_request_delivery.id
    val Status_Reporting_Thread_control_process_status_reporting_id = Arch.Autopilot_Engagement_System_Instance_control_process_status_reporting.id
    val CSA_Enable_Delivery_Thread_control_process_csa_enable_delivery_id = Arch.Autopilot_Engagement_System_Instance_control_process_csa_enable_delivery.id

    def genUniqueSuiteName(path: Os.Path, prefix: String): String = {
      var i = 0
      while(true) {
        val cand = path / s"${prefix}_${i}.scala"
        if (!cand.exists) {
          return s"${prefix}_${i}"
        }
        i = i + 1
      }
      halt("Infeasible")
    }

    for (p <- testCases) {
      art.Art.BridgeId.fromZ(p._1) match {
        case FCI_Command_Intake_Thread_control_process_fci_command_intake_id =>
          val prefix = "FCI_Command_Intake_Thread_control_process_fci_command_intake_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","FAA_Autopilot_Engagement")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.FAA_Autopilot_Engagement
                |
                |import org.sireum._
                |import scp_candidate.FAA_Autopilot_Engagement._
                |
                |class ${suiteName} extends FCI_Command_Intake_Thread_control_process_fci_command_intake_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Engagement_Decision_Thread_control_process_engagement_decision_id =>
          val prefix = "Engagement_Decision_Thread_control_process_engagement_decision_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","FAA_Autopilot_Engagement")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.FAA_Autopilot_Engagement
                |
                |import org.sireum._
                |import scp_candidate.FAA_Autopilot_Engagement._
                |
                |class ${suiteName} extends Engagement_Decision_Thread_control_process_engagement_decision_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Guidance_Request_Delivery_Thread_control_process_guidance_request_delivery_id =>
          val prefix = "Guidance_Request_Delivery_Thread_control_process_guidance_request_delivery_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","FAA_Autopilot_Engagement")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.FAA_Autopilot_Engagement
                |
                |import org.sireum._
                |import scp_candidate.FAA_Autopilot_Engagement._
                |
                |class ${suiteName} extends Guidance_Request_Delivery_Thread_control_process_guidance_request_delivery_ScalaTest {
                |  val verbose: B = T
                |
                |  ${p._2}
                |}"""
          val filename = path / s"${suiteName}.scala"
          filename.writeOver(testSuite.render)
          println(s"Wrote: ${filename.toUri}")
        case Status_Reporting_Thread_control_process_status_reporting_id =>
          val prefix = "Status_Reporting_Thread_control_process_status_reporting_RM_TestSuite"
          val path = testRoot /+ ISZ("scp_candidate","FAA_Autopilot_Engagement")
          val suiteName = genUniqueSuiteName(path, prefix)

          val testSuite =
            st"""package scp_candidate.FAA_Autopilot_Engagement
                |
                |import org.sireum._
                |import scp_candidate.FAA_Autopilot_Engagement._
                |
