  def getUpdates(bridge_id: art.Art.BridgeId, observationKind: ObservationKind.Type, container: art.DataContent): Map[String, String] = {
    observationKind match {
      case scp_candidate.runtimemonitor.ObservationKind.Autopilot_Engagement_System_Instance_control_process_fci_command_intake_postInit =>
        var updates: Map[String, String] = Map.empty
        val postContainer = container.asInstanceOf[scp_candidate.FAA_Autopilot_Engagement.FCI_Command_Intake_Thread_control_process_fci_command_intake_PostState_Container_PS]
        updates = updates + s"${bridge_id}_Out_engage_ap_out" ~> postContainer.api_engage_ap_out.string
        updates = updates + s"${bridge_id}_Out_command_status_out" ~> postContainer.api_command_status_out.string
